  "prime": {
    "parameters": [
      "x"
    ],
    "formula": "⌊x⌋=x ∧ x>1 ∧ ¬properFactor(x)"
  },
  "composite": {
    "parameters": [
      "x"
    ],
    "formula": "⌊x⌋=x ∧ x>1 ∧ properFactor(x)"
  },
